GB = "\"Gladiator Beast\""
def tag(n): return "Al final de la Battle Phase, si esta carta atacó o fue atacada: puedes barajarla al Deck; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"%s\"." % n
def tagb(n): return "Al final de la Battle Phase, si esta carta batalló: puedes barajarla al Deck; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"%s\"." % n
SS = "Cuando esta carta sea Invocada de Modo Especial por el efecto de un monstruo " + GB + ": "
SSI = "Si esta carta es Invocada de Modo Especial por el efecto de un monstruo " + GB + ": "
WAS = "Si esta carta fue Invocada de Modo Especial por el efecto de un monstruo " + GB
CONTACT = "Primero debe ser Invocado de Modo Especial (desde tu Deck Extra) barajando al Deck las cartas indicadas que controles. (No usas \"Polymerization\".)"
EQ = "Equipa sólo a un monstruo " + GB + ". "
EQB = " Cuando el monstruo equipado sea devuelto de tu lado del Campo al Deck y esta carta sea mandada al Cementerio, devuelve esta carta a tu mano."
ES = {
"Gladiator Beast Andabata": "\"Gladiator Beast Augustus\" + 2 monstruos " + GB + "\n" + CONTACT + " Si es Invocado de esta forma: puedes Invocar de Modo Especial 1 Monstruo de Fusión " + GB + " de Nivel 7 o menor de tu Deck Extra, ignorando sus condiciones de Invocación. Al final de la Battle Phase, si esta carta batalló: puedes devolverla al Deck Extra; Invoca de Modo Especial 2 monstruos " + GB + " de tu Deck.",
"Gladiator Beast Claudius": "5 monstruos " + GB + "\nPrimero debe ser Invocado de Modo Especial (desde tu Deck Extra) barajando al Deck/Deck Extra las cartas indicadas desde tu Campo y/o Cementerio. Si es Invocado de esta forma: puedes realizar tu próxima Battle Phase dos veces. Una vez por turno, si tu adversario activa un efecto de monstruo (excepto durante el Damage Step): puedes activar el siguiente efecto según de quién sea el turno:\n● Tuyo: Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck.\n● De tu adversario: Invoca de Modo Especial 1 monstruo " + GB + " de Nivel 11 o menor de tu Deck Extra, ignorando sus condiciones de Invocación.",
"Gladiator Beast Domitianus": "\"Gladiator Beast Vespasius\" + 2 monstruos " + GB + "\n" + CONTACT + " Una vez por turno, cuando tu adversario activa un efecto de monstruo (Efecto Rápido): puedes negar la activación y, si lo haces, destruirlo. Tú eliges los objetivos de los ataques de tu adversario. Al final de la Battle Phase, si esta carta batalló: puedes devolver esta carta al Deck Extra; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck.",
"Gladiator Beast Essedarii": "2 monstruos " + GB + "\n" + CONTACT,
"Gladiator Beast Gaiodiaz": "\"Gladiator Beast Spartacus\" + 1 monstruo " + GB + "\nEsta carta sólo puede ser Invocada de Modo Especial desde tu Deck Extra, devolviendo al Deck las cartas indicadas que controles. (No usas \"Polymerization\".) Cuando esta carta destruye un monstruo en batalla y lo manda al Cementerio, inflige a tu adversario daño igual a la DEF del monstruo destruido. Al final de la Battle Phase, si esta carta atacó o fue atacada, puedes devolverla al Deck Extra para Invocar de Modo Especial 2 monstruos " + GB + " de tu Deck, excepto \"Gladiator Beast Spartacus\".",
"Gladiator Beast Gyzarus": "\"Gladiator Beast Bestiari\" + 1 monstruo " + GB + "\n" + CONTACT + " Cuando esta carta sea Invocada de Modo Especial: puedes seleccionar hasta 2 cartas en el Campo; destruye esos objetivos. Al final de la Battle Phase, si esta carta batalló: puedes devolverla al Deck Extra; Invoca de Modo Especial 2 monstruos " + GB + " de tu Deck, excepto \"Gladiator Beast Bestiari\".",
"Gladiator Beast Heraklinos": "\"Gladiator Beast Laquari\" + 2 monstruos " + GB + "\n" + CONTACT + " Cuando se activa una Carta Mágica/de Trampa (Efecto Rápido): puedes descartar 1 carta; niega la activación y, si lo haces, destrúyela. Esta carta debe estar boca arriba en el Campo para activar y resolver este efecto.",
"Gladiator Beast Nerokius": "3 monstruos " + GB + "\n" + CONTACT + " No puede ser destruido en batalla. Si esta carta ataca o es atacada, tu adversario no puede activar cartas ni efectos hasta el final del Damage Step. Al final de la Battle Phase, si esta carta atacó o fue atacada: puedes barajarla al Deck Extra; Invoca de Modo Especial 2 monstruos " + GB + " de tu Deck.",
"Gladiator Beast Tamer Editor": "2 monstruos " + GB + " de Nivel 5 o mayor\n" + CONTACT + " No puede ser usado como Material de Fusión. Una vez por turno: puedes Invocar de Modo Especial 1 Monstruo de Fusión " + GB + " de tu Deck Extra, excepto \"Gladiator Beast Tamer Editor\", ignorando sus condiciones de Invocación. Al final de la Battle Phase, si tu monstruo " + GB + " batalló: puedes barajar ese monstruo al Deck o Deck Extra; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck.",
"Test Ape": "Cuando esta carta sea destruida en batalla y mandada al Cementerio, puedes Invocar de Modo Especial 1 monstruo " + GB + " de Nivel 4 o menor de tu Deck.",
"Gladiator Beast Gistel": "Al final de la Battle Phase, si esta carta batalló: puedes barajar esta carta al Deck; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"Gladiator Beast Gistel\". Sólo puedes usar cada uno de los siguientes efectos de \"Gladiator Beast Gistel\" una vez por turno. Puedes revelar esta carta y 1 monstruo " + GB + " en tu mano; Invoca ambos de Modo Especial. " + SSI + "puedes añadir a tu mano 1 Carta Mágica/de Trampa \"Gladiator\" de tu Deck.",
"Gladiator Beast Murmillo": SS + "selecciona 1 monstruo boca arriba; destruye ese objetivo. " + tag("Gladiator Beast Murmillo"),
"Gladiator Beast Retiari": "Cuando esta carta sea Invocada de Modo Especial por el efecto de un monstruo " + GB + ", puedes desterrar 1 carta del Cementerio de tu adversario. Al final de la Battle Phase, si esta carta atacó o fue atacada, puedes devolverla al Deck para Invocar de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"Gladiator Beast Retiari\".",
"Gladiator Beast Sagittarii": SSI + "puedes descartar 1 carta " + GB + "; roba 2 cartas. " + tagb("Gladiator Beast Sagittarii"),
"Gladiator Beast Samnite": "Cuando esta carta, que fue Invocada de Modo Especial por el efecto de un monstruo " + GB + ", destruye un monstruo de tu adversario en batalla y lo manda al Cementerio: puedes añadir a tu mano 1 carta " + GB + " de tu Deck. " + tagb("Gladiator Beast Samnite"),
"Gladiator Beast Torax": WAS + ", al final de cualquier Battle Phase en la que esta carta atacó o fue atacada, puedes devolverla al Deck para robar 1 carta.",
"Test Tiger": "Si controlas un monstruo " + GB + " boca arriba, puedes Invocar esta carta de Modo Especial (desde tu mano). Puedes Sacrificar esta carta para seleccionar 1 monstruo " + GB + " boca arriba que controles; baraja ese objetivo al Deck, después Invoca de Modo Especial 1 " + GB + " de tu Deck, y trátalo como si hubiera sido Invocado de Modo Especial por el efecto de un monstruo " + GB + ".",
"Gladiator Beast Attorix": SSI + "puedes mandar al Cementerio 1 monstruo " + GB + " de tu Deck o Deck Extra, excepto \"Gladiator Beast Attorix\"; hasta la End Phase, el Nivel y el nombre de esta carta se vuelven los mismos que los del monstruo mandado al Cementerio. " + tagb("Gladiator Beast Attorix"),
"Gladiator Beast Bestiari": SSI + "selecciona 1 Carta Mágica/de Trampa en el Campo; destruye ese objetivo. " + tag("Gladiator Beast Bestiari"),
"Gladiator Beast Darius": SS + "puedes seleccionar 1 monstruo " + GB + " en tu Cementerio; Invoca de Modo Especial ese objetivo, pero sus efectos son negados. Cuando esta carta deja el Campo, baraja ese monstruo al Deck. " + tagb("Gladiator Beast Darius"),
"Gladiator Beast Dimacari": WAS + ", puede atacar dos veces durante cada Battle Phase. Al final de la Battle Phase, si esta carta atacó o fue atacada, puedes devolverla al Deck para Invocar de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"Gladiator Beast Dimacari\".",
"Gladiator Beast Equeste": SSI + "selecciona 1 carta " + GB + " en tu Cementerio; añade ese objetivo a tu mano. " + tagb("Gladiator Beast Equeste"),
"Gladiator Beast Hoplomus": WAS + ", su DEF original se convierte en 2400. " + tag("Gladiator Beast Hoplomus"),
"Gladiator Beast Lanista": SS + "puedes seleccionar 1 monstruo " + GB + " en tu Cementerio; destierra ese objetivo y, si lo haces, el nombre de esta carta se convierte en el nombre del objetivo hasta la End Phase. " + tagb("Gladiator Beast Lanista"),
"Gladiator Beast Laquari": WAS + ", su ATK original se convierte en 2100. " + tag("Gladiator Beast Laquari"),
"Gladiator Beast Secutor": WAS + ", al final de cualquier Battle Phase en la que esta carta atacó o fue atacada: Invoca de Modo Especial 2 monstruos " + GB + " de tu Deck, excepto \"Gladiator Beast Secutor\".",
"Gladiator Beast Tygerius": "Esta carta no puede ser usada como Monstruo Material de Fusión. Cuando esta carta sea Invocada de Modo Especial por el efecto de un monstruo " + GB + ", puedes descartar 1 carta " + GB + " para añadir a tu mano 1 monstruo " + GB + " de tu Deck.",
"Test Bear": "Si controlas un monstruo " + GB + " Invocado de Modo Especial desde el Deck/Deck Extra, puedes Invocar esta carta de Modo Especial (desde tu mano). Sólo puedes Invocar de Modo Especial a \"Test Bear\" una vez por turno de esta forma. Puedes Sacrificar esta carta y después barajar al Deck/Deck Extra 1 monstruo " + GB + " de tu mano o boca arriba en tu Campo; Invoca de Modo Especial hasta 2 monstruos " + GB + " de tu Deck. (Esto se trata como una Invocación Especial por el efecto de un monstruo " + GB + ".) Sólo puedes usar este efecto de \"Test Bear\" una vez por turno.",
"Gladiator Beast Noxious": "Cuando un monstruo de tu adversario declara un ataque directo: puedes Invocar esta carta de Modo Especial desde tu mano y, si lo haces, cambia el objetivo del ataque a esta carta y procede al cálculo de daño. Esta carta no puede ser destruida en esa batalla. " + SSI + "puedes mandar al Cementerio 1 monstruo " + GB + " de tu Deck. " + tagb("Gladiator Beast Noxious"),
"Gladiator Beast Spartacus": "No puede ser Invocado de Modo Especial por el efecto de una carta, excepto por el efecto de \"Gladiator Beast Hoplomus\". Si esta carta es Invocada de Modo Especial: añade a tu mano 1 Carta Mágica de Equipo " + GB + " de tu Deck. Al final de la Battle Phase, si esta carta batalló: puedes barajar esta carta al Deck; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"Gladiator Beast Spartacus\".",
"Gladiator Beast Alexander": "No puede ser Invocado de Modo Especial por el efecto de una carta, excepto por el efecto de \"Gladiator Beast Dimacari\". Esta carta Invocada de Modo Especial no es afectada por efectos de Cartas Mágicas. Al final de la Battle Phase, si esta carta batalló: puedes barajar esta carta al Deck; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"Gladiator Beast Alexander\".",
"Gladiator Beast Octavius": SS + "selecciona 1 Carta Mágica o de Trampa boca abajo en la Zona de Magia y Trampa; destruye ese objetivo. Al final de tu Battle Phase, si esta carta atacó o fue atacada: baraja esta carta al Deck o descarta 1 carta.",
"Gladiator Beast Vespasius": "Al comienzo del Damage Step, si tu monstruo " + GB + " batalla con un monstruo: puedes Invocar esta carta de Modo Especial desde tu mano. Sólo puedes usar este efecto de \"Gladiator Beast Vespasius\" una vez por turno. Mientras controles esta carta, Invocada de Modo Especial por el efecto de un monstruo " + GB + ", todos los monstruos que controles ganan 500 ATK. Al final de la Battle Phase, si esta carta batalló: puedes barajar esta carta al Deck; Invoca de Modo Especial 1 monstruo " + GB + " de tu Deck, excepto \"Gladiator Beast Vespasius\".",
"Gladiator Beast Augustus": SS + "puedes Invocar de Modo Especial 1 monstruo " + GB + " de tu mano en Posición de Defensa. Barájalo al Deck durante la End Phase. " + tag("Gladiator Beast Augustus"),
"Colosseum - Cage of the Gladiator Beasts": "Pon 1 Contador en esta carta cada vez que un monstruo sea Invocado de Modo Especial desde el Deck de cualquier jugador. Todos los monstruos " + GB + " ganan 100 ATK y DEF por cada uno de estos contadores en esta carta. Si esta carta fuera a ser destruida por efecto de una carta, puedes descartar 1 \"Colosseum - Cage of the Gladiator Beasts\" para evitar que esta carta sea destruida.",
"Flavian - Colosseum of the Gladiator Beasts": "Puedes descartar 1 carta; añade a tu mano 1 monstruo " + GB + " de tu Deck. Cuando un monstruo de tu adversario declara un ataque: puedes Invocar de Modo Especial 1 monstruo " + GB + " de tu Deck, y no puede ser destruido en batalla. Durante la End Phase, si un monstruo " + GB + " fue Invocado de Modo Especial desde tu Deck este turno: puedes Colocar 1 Carta de Trampa \"Gladiator\" de tu Deck. Sólo puedes usar cada efecto de \"Flavian - Colosseum of the Gladiator Beasts\" una vez por turno.",
"Gladiator Beast United": "Durante la Battle Phase: baraja al Deck, desde tu mano, Campo o Cementerio, los Materiales de Fusión listados en un Monstruo de Fusión " + GB + ", y después Invoca de Modo Especial ese Monstruo de Fusión desde tu Deck Extra, ignorando sus condiciones de Invocación. Sólo puedes activar 1 \"Gladiator Beast United\" por turno. No puedes declarar ataques el turno en que actives esta carta, excepto con monstruos " + GB + ".",
"Gladiator Beast's Battle Gladius": EQ + "Gana 300 ATK." + EQB,
"Gladiator Beast's Battle Halberd": EQ + "Cuando ataca, destruye 1 Carta Mágica o de Trampa al final del Damage Step." + EQB,
"Gladiator Beast's Battle Manica": EQ + "No puede ser destruido en batalla (el cálculo de daño se aplica normalmente)." + EQB,
"Gladiator Beast's Comeback": "Invoca de Modo Especial 1 monstruo " + GB + " de tu mano o Cementerio, con un Tipo diferente al de los monstruos que controles. No puede ser destruido en batalla.",
"Gladiator Beast's Respite": "Baraja al Deck 2 cartas " + GB + " de tu mano y después roba 3 cartas.",
"Gladiator Proving Ground": "Añade a tu mano 1 monstruo " + GB + " de Nivel 4 o menor de tu Deck.",
"Gladiator Rejection": "Tu adversario no puede seleccionar con efectos de cartas a los monstruos " + GB + " que controles, excepto durante la Battle Phase. Si uno o más monstruos " + GB + " son Invocados de Modo Especial desde tu Deck Principal (excepto durante el Damage Step): puedes Invocar de Modo Especial, en Posición de Defensa, 1 monstruo " + GB + " de tu Deck con un Tipo diferente al de los monstruos que controles. Sólo puedes usar este efecto de \"Gladiator Rejection\" una vez por turno.",
"Gladiator Taming": "Si hay un monstruo " + GB + " boca arriba en el Campo, activa 1 de estos efectos:\n● Selecciona 1 monstruo boca arriba que controle tu adversario y cambia su posición de batalla.\n● Selecciona 1 monstruo " + GB + " boca arriba que controle tu adversario y toma su control hasta la End Phase.",
"Gladiator's Return": "Selecciona 3 cartas " + GB + " en tu Cementerio; baraja los 3 objetivos al Deck y después roba 1 carta.",
"Indomitable Gladiator Beast": "El monstruo " + GB + " boca arriba que controles y que selecciones gana 500 ATK hasta la End Phase. Mientras esta carta esté en tu Cementerio, puedes devolver al Deck 2 cartas " + GB + " de tu Cementerio para devolver esta carta a tu mano.",
"Defensive Tactics": "Si controlas un monstruo " + GB + " boca arriba: durante el resto de este turno, los monstruos que controles no pueden ser destruidos en batalla, y cualquier daño de batalla que recibas se reduce a 0. Después de que esta carta se resuelva, ponla en el fondo de tu Deck.",
"Disarm": "Devuelve al Deck 1 carta " + GB + " de tu mano, y niega la activación y el efecto de una Carta Mágica, y destrúyela.",
"Double Tag Team": "Activa sólo cuando Invoques de Modo Especial un monstruo " + GB + ". Invoca de Modo Especial 1 monstruo " + GB + " de Nivel 4 o menor de tu mano o Deck.",
"Gladiator Beast Charge": "Selecciona cartas boca arriba en el Campo, hasta el número de monstruos " + GB + " con nombres diferentes que controles; destrúyelas.",
"Gladiator Beast War Chariot": "Cuando se activa el efecto de un Monstruo de Efecto, mientras controlas un monstruo " + GB + ": niega la activación y, si lo haces, destrúyelo.",
"Gladiator Lash": "Activa sólo cuando Invoques de Modo Especial un monstruo " + GB + ". Tu adversario descarta 1 carta de su elección.",
"Gladiator Naumachia": "Mientras controles un monstruo " + GB + ", todos los monstruos que controle tu adversario deben atacar, si pueden. Una vez por turno: puedes barajar al Deck Principal 1 monstruo " + GB + " de tu mano o Cementerio y después seleccionar 1 monstruo " + GB + " que controles; gana ATK igual a su DEF original hasta el final de este turno (incluso si esta carta deja el Campo). Si esta carta en la Zona de Magia y Trampa es destruida por efecto de una carta: puedes activar este efecto; este turno, los monstruos " + GB + " que controles no pueden ser destruidos en batalla.",
"Parry": "Devuelve al Deck 1 carta " + GB + " de tu mano, y niega la activación y el efecto de una Carta de Trampa, y destrúyela.",
"Trojan Gladiator Beast": "Invoca de Modo Especial 1 monstruo " + GB + " de tu mano en el lado del Campo de tu adversario. Después, roba 1 carta.",
}
